#!/usr/bin/env python3
"""Сохраняет лог текущей сессии Claude Code в папку sessions/.

Вызывается хуками (UserPromptSubmit, Stop, PreCompact, SessionEnd) и получает
на stdin JSON с полями session_id и transcript_path. На каждый вызов файлы
сессии перезаписываются целиком, поэтому в sessions/ всегда лежит актуальная
версия диалога:

  sessions/<дата-время старта>_<id>.md     — читаемый диалог
  sessions/raw/<дата-время старта>_<id>.jsonl — полная копия исходного лога
"""

import json
import shutil
import sys
from datetime import datetime
from pathlib import Path

PROJECT_DIR = Path(__file__).resolve().parents[2]
SESSIONS_DIR = PROJECT_DIR / "sessions"
RAW_DIR = SESSIONS_DIR / "raw"
MAX_TOOL_OUTPUT = 4000


def load_entries(path: Path) -> list[dict]:
    entries = []
    with path.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entries.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return entries


def start_time(entries: list[dict]) -> datetime:
    for e in entries:
        ts = e.get("timestamp")
        if ts:
            try:
                return datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone()
            except ValueError:
                pass
    return datetime.now().astimezone()


def fmt_time(ts: str | None) -> str:
    if not ts:
        return ""
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone().strftime("%H:%M:%S")
    except ValueError:
        return ts


def clip(text: str) -> str:
    if len(text) > MAX_TOOL_OUTPUT:
        return text[:MAX_TOOL_OUTPUT] + f"\n… (обрезано, всего {len(text)} символов — полный текст в raw/)"
    return text


def block_text(content) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                if c.get("type") == "text":
                    parts.append(c.get("text", ""))
                elif c.get("type") == "image":
                    parts.append("[изображение]")
            else:
                parts.append(str(c))
        return "\n".join(parts)
    return str(content)


def fence(text: str, lang: str = "") -> str:
    ticks = "```"
    while ticks in text:
        ticks += "`"
    return f"{ticks}{lang}\n{text}\n{ticks}"


def render(entries: list[dict], session_id: str) -> str:
    out = [f"# Сессия {start_time(entries):%Y-%m-%d %H:%M}", "", f"ID: `{session_id}`", ""]
    for e in entries:
        etype = e.get("type")
        if etype == "summary" and e.get("summary"):
            out += ["---", f"_Сводка: {e['summary']}_", ""]
            continue
        if etype not in ("user", "assistant") or e.get("isSidechain"):
            continue
        msg = e.get("message") or {}
        content = msg.get("content")
        t = fmt_time(e.get("timestamp"))

        if etype == "user":
            if e.get("isCompactSummary"):
                out += ["---", f"### Сжатие контекста ({t})", "", block_text(content), ""]
                continue
            if isinstance(content, str):
                out += ["---", f"## 👤 Пользователь ({t})", "", content, ""]
                continue
            for c in content or []:
                if not isinstance(c, dict):
                    continue
                if c.get("type") == "tool_result":
                    res = clip(block_text(c.get("content", "")))
                    label = "Результат (ошибка)" if c.get("is_error") else "Результат"
                    out += [f"<details><summary>{label}</summary>", "", fence(res), "", "</details>", ""]
                elif c.get("type") == "text":
                    out += ["---", f"## 👤 Пользователь ({t})", "", c.get("text", ""), ""]
                elif c.get("type") == "image":
                    out += ["[изображение]", ""]
        else:
            for c in content or []:
                if not isinstance(c, dict):
                    continue
                if c.get("type") == "text" and c.get("text", "").strip():
                    out += [f"## 🤖 Claude ({t})", "", c["text"], ""]
                elif c.get("type") == "tool_use":
                    args = json.dumps(c.get("input", {}), ensure_ascii=False, indent=2)
                    out += [f"**🔧 {c.get('name')}**", "", fence(clip(args), "json"), ""]
    return "\n".join(out) + "\n"


def main() -> None:
    try:
        payload = json.load(sys.stdin)
    except json.JSONDecodeError:
        payload = {}
    transcript = payload.get("transcript_path")
    if not transcript or not Path(transcript).is_file():
        return
    transcript = Path(transcript)
    session_id = payload.get("session_id") or transcript.stem

    entries = load_entries(transcript)
    base = f"{start_time(entries):%Y-%m-%d_%H-%M-%S}_{session_id[:8]}"

    RAW_DIR.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(transcript, RAW_DIR / f"{base}.jsonl")
    (SESSIONS_DIR / f"{base}.md").write_text(render(entries, session_id), encoding="utf-8")


if __name__ == "__main__":
    main()

